import { Component, computed, input, output, signal } from '@angular/core';
import { TablerIconComponent, IconCheck, IconX } from '@tabler/icons-angular';
import { HrmAvatar } from '../data-display/hrm-avatar';
import { HrmStatusCell, HrmStatusTone } from '../table-cells/hrm-status-cell';

/** 1 bước trong quy trình phê duyệt. Nhãn hiển thị (title/stateLabel/role/time) do bên gọi cấp (i18n-sạch). */
export interface HrmApprovalStep {
  /** Tiêu đề bước — VD "Gửi yêu cầu", "Quản lý cấp 1". */
  title?: string;
  /** Tên người thực hiện/duyệt. */
  name: string;
  /** Chức danh/vai trò (dòng phụ dưới tên). */
  role?: string;
  /** Mốc thời gian hiển thị (đã format) — thường cho bước đã thực hiện. */
  time?: string;
  /** Trạng thái bước: approved (đã qua) · current (đang chờ bước này) · waiting (chưa tới) · rejected (từ chối). */
  state: 'approved' | 'current' | 'waiting' | 'rejected';
  /** Nhãn badge cạnh tên (i18n) — VD "Chờ duyệt", "Đã duyệt". Bỏ trống → ẩn. */
  stateLabel?: string;
}

/** hrm-approval-flow — quy trình phê duyệt RESPONSIVE (container query):
 *  · Container HẸP → timeline DỌC (node trái, thân phải).
 *  · Container RỘNG (≥520px) → stepper NGANG (node trên, thân dưới, đường nối ngang).
 *  Node mang state (✓ đã duyệt · số/vòng đang chờ · ✗ từ chối); **badge trạng thái CHỈ hiện ở
 *  bước đang chờ / từ chối** (bước đã xong → node xanh + thời gian đã đủ nghĩa, bỏ badge cho gọn).
 *  Toàn token → tự Light/Dark. API giữ nguyên (steps/collapsedCount/moreLabel/collapseLabel).
 *
 *  <hrm-approval-flow [steps]="steps" moreLabel="+2 người phê duyệt" (moreClick)="..." /> */
@Component({
  selector: 'hrm-approval-flow',
  imports: [TablerIconComponent, HrmStatusCell, HrmAvatar],
  template: `
    <div class="af">
      @for (s of visibleSteps(); track $index; let i = $index) {
        <div class="af-step" [attr.data-state]="s.state">
          <span class="af-node">
            @if (s.state === 'approved') { <tabler-icon [icon]="icCheck" [size]="14" /> }
            @else if (s.state === 'rejected') { <tabler-icon [icon]="icX" [size]="14" /> }
            @else { {{ i + 1 }} }
          </span>
          <div class="af-body">
            <div class="af-head">
              @if (s.title) { <span class="af-title">{{ s.title }}</span> }
              <hrm-status class="af-status" [status]="statusToneOf(s.state)" [label]="stepLabel(s)" variant="badge" [dot]="true" />
            </div>
            <div class="af-person">
              <hrm-avatar [text]="initialsOf(s.name)" [size]="36" [colorful]="true" [colorSeed]="s.name" />
              <div class="af-who">
                <div class="af-name">{{ s.name }}</div>
                @if (s.role) { <div class="af-role">{{ s.role }}</div> }
                @if (s.time) { <div class="af-time">{{ s.time }}</div> }
              </div>
            </div>
          </div>
        </div>
      }
      @if (canToggle()) {
        <button type="button" class="af-more" (click)="toggle()">
          {{ expanded() ? collapseLabel() : moreLabel() }}
        </button>
      }
    </div>
  `,
  host: { class: 'hrm-approval-flow' },
  styles: [`
    /* container NÊN có TÊN (hrm-af) → @container đổi bố cục theo BỀ RỘNG của CHÍNH component (không
       phụ thuộc container cha ngoài). Hẹp = timeline dọc · ≥400px = stepper ngang. */
    :host { display: block; container: hrm-af / inline-size; }
    .af { display: flex; flex-direction: column; }

    /* ===== HẸP (mặc định): TIMELINE DỌC — node trái, thân phải, đường nối dọc ===== */
    .af-step { position: relative; display: flex; gap: 12px; padding-bottom: 18px; }
    .af-step:last-child { padding-bottom: 0; }

    .af-node {
      position: relative; z-index: 1; flex: none;
      display: grid; place-items: center; width: 24px; height: 24px;
      border-radius: var(--radius-full); font-size: var(--fs-12); font-weight: 600;
      background: var(--bg-surface-subtle); color: var(--text-sub); border: 1.5px solid transparent;
    }
    /* Đường nối tới bước kế — dọc (canh tâm node). Xanh khi bước này đã duyệt. */
    .af-step:not(:last-child)::after {
      content: ''; position: absolute; z-index: 0; background: var(--border-sub); border-radius: var(--radius-full);
      left: 11px; top: 28px; bottom: 6px; width: 2px;
    }
    .af-step[data-state='approved'] .af-node { background: var(--bg-surface); border-color: var(--primary-base); color: var(--primary-base); }
    .af-step[data-state='approved']:not(:last-child)::after { background: var(--primary-base); }

    /* Bước ĐANG CHỜ: chấm solid brand + vòng nét đứt xoay. */
    .af-step[data-state='current'] .af-node { background: var(--primary-base); border-color: var(--primary-base); color: var(--static-white, #fff); }
    .af-step[data-state='current'] .af-node::before {
      content: ''; position: absolute; inset: -5px; border-radius: var(--radius-full);
      border: 1.5px dashed var(--primary-base); animation: hrm-af-spin 6s linear infinite;
    }
    @keyframes hrm-af-spin { to { transform: rotate(360deg); } }
    @media (prefers-reduced-motion: reduce) { .af-step[data-state='current'] .af-node::before { animation: none; } }
    .af-step[data-state='rejected'] .af-node { background: var(--error-base); border-color: var(--error-base); color: var(--static-white, #fff); }

    /* Thân bước — cột: HEAD (title nhỏ + STATUS pill cùng dòng) rồi người duyệt (avatar trái + tên +
       subtext). Timeline: status đẩy PHẢI (margin-left:auto). Stepper: status kế title (override dưới). */
    .af-body { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 4px; }
    .af-head { display: flex; align-items: center; gap: var(--space-2, 8px); min-width: 0; }
    .af-title { font-size: var(--fs-11); font-weight: 600; text-transform: uppercase; letter-spacing: .04em; color: var(--text-soft); min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
    .af-status { margin-left: auto; flex: none; }
    .af-person { display: flex; align-items: flex-start; gap: 10px; min-width: 0; margin-top: 2px; }
    .af-who { flex: 1; min-width: 0; }
    .af-name { font-size: var(--fs-14); font-weight: 600; color: var(--text-strong); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    .af-role { margin-top: 1px; font-size: var(--fs-12); color: var(--text-sub); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    .af-time { margin-top: 1px; font-size: var(--fs-12); color: var(--text-soft); font-variant-numeric: tabular-nums; }
    .af-more {
      align-self: flex-start; margin: 8px 0 0 36px; padding: 0; border: 0; background: transparent;
      cursor: pointer; font: inherit; font-size: var(--fs-13); font-weight: 500; color: var(--primary-base);
    }
    .af-more:hover { text-decoration: underline; }

    /* ===== RỘNG (≥400px): STEPPER NGANG — node trên · title · người duyệt · STATUS pill DƯỚI CÙNG (theo ảnh mẫu) ===== */
    @container hrm-af (min-width: 400px) {
      .af { flex-direction: row; align-items: flex-start; }
      /* Node trên · nội dung CANH TRÁI theo điểm node; STATUS pill KẾ BÊN title (cùng dòng head). */
      .af-step { flex: 1 1 0; min-width: 0; flex-direction: column; align-items: flex-start; text-align: left; gap: 10px; padding-bottom: 0; }
      .af-step:not(:last-child)::after { left: 12px; right: auto; top: 11px; bottom: auto; width: 100%; height: 2px; }
      .af-body { align-items: flex-start; gap: 6px; width: 100%; }
      .af-head { justify-content: flex-start; }
      .af-title { line-height: 1.3; white-space: normal; }
      .af-status { margin-left: 0; }
      .af-person { justify-content: flex-start; max-width: 100%; }
      .af-who { flex: 0 1 auto; min-width: 0; }
      .af-name, .af-role, .af-time { white-space: normal; }
      .af-more { align-self: flex-start; margin: 0; }
    }
  `],
})
export class HrmApprovalFlow {
  /** Các bước duyệt theo thứ tự. */
  readonly steps = input<HrmApprovalStep[]>([]);
  /** Nhãn nút mở rộng "+N người phê duyệt" (i18n) — hiện khi đang thu gọn. */
  readonly moreLabel = input('');
  /** Nhãn nút "Thu gọn" (i18n) — hiện khi đã mở rộng. */
  readonly collapseLabel = input('Thu gọn');
  /** Số bước hiển thị khi THU GỌN. 0 = hiện hết (không thu gọn). */
  readonly collapsedCount = input(0);
  /** Bấm nút (giữ để tương thích cũ; component tự quản lý mở/thu). */
  readonly moreClick = output<void>();

  /** Trạng thái mở rộng nội bộ. */
  protected readonly expanded = signal(false);
  protected toggle(): void { this.expanded.update((v) => !v); this.moreClick.emit(); }

  /** Có nút mở/thu không: khi collapsedCount > 0 và tổng bước vượt collapsedCount. */
  protected readonly canToggle = computed(() => this.collapsedCount() > 0 && this.steps().length > this.collapsedCount());
  /** Bước hiển thị: mở rộng (hoặc không cấu hình thu gọn) → tất cả; else cắt còn collapsedCount. */
  protected readonly visibleSteps = computed<HrmApprovalStep[]>(() => {
    const all = this.steps();
    if (this.expanded() || !this.canToggle()) return all;
    return all.slice(0, this.collapsedCount());
  });

  protected readonly icCheck = IconCheck;
  protected readonly icX = IconX;

  /** Nhãn status của bước (pill) — theo ảnh mẫu MỌI bước đều có pill. Dùng stateLabel bên gọi cấp;
   *  thiếu → suy mặc định theo state. Vị trí pill: phải-trên (timeline) / dưới cùng (stepper). */
  protected stepLabel(s: HrmApprovalStep): string {
    if (s.stateLabel) return s.stateLabel;
    return s.state === 'approved' ? 'Đã duyệt' : s.state === 'current' ? 'Đang xử lý' : s.state === 'rejected' ? 'Từ chối' : 'Chờ';
  }

  /** Map trạng thái bước → tông status hệ thống (đồng bộ hrm-status). */
  protected statusToneOf(s: HrmApprovalStep['state']): HrmStatusTone {
    return s === 'approved' ? 'success' : s === 'current' ? 'warning' : s === 'rejected' ? 'error' : 'neutral';
  }

  /** Chữ cái đầu (từ đầu + từ cuối) — khớp cách hrm-user-cell suy initials. */
  protected initialsOf(name: string): string {
    const p = name.trim().split(/\s+/);
    return ((p[0]?.[0] ?? '') + (p.length > 1 ? p[p.length - 1][0] : '')).toUpperCase();
  }

}
